namespace sv_3ca9250d03264fc5aeebf88ae837a0ce.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service (one instance per circuit) that holds theme state
/// and notifies subscribers on change.
/// </summary>
public class ThemeService
{
    private Theme _currentTheme = Theme.System;
    private string _accentColor = "#6366f1";

    public Theme CurrentTheme
    {
        get => _currentTheme;
        set
        {
            if (_currentTheme == value) return;
            _currentTheme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@implements IDisposable
@inject Services.ThemeService ThemeService

<span class="theme-indicator" style="color: @ThemeService.AccentColor;" title="Current theme">
    @GetIcon()  @ThemeService.CurrentTheme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += OnThemeChanged;
    }

    private void OnThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetIcon() => ThemeService.CurrentTheme switch
    {
        Services.Theme.Light => "☀️",
        Services.Theme.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
    }
}

@implements IDisposable
@inject Services.ThemeService ThemeService

<div class="theme-toggle">
    <button @onclick="CycleTheme" style="border-color: @ThemeService.AccentColor;">
        @GetIcon() @ThemeService.CurrentTheme
    </button>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += OnThemeChanged;
    }

    private void CycleTheme()
    {
        ThemeService.CurrentTheme = ThemeService.CurrentTheme switch
        {
            Services.Theme.Light => Services.Theme.Dark,
            Services.Theme.Dark => Services.Theme.System,
            _ => Services.Theme.Light
        };
    }

    private string GetIcon() => ThemeService.CurrentTheme switch
    {
        Services.Theme.Light => "☀️",
        Services.Theme.Dark => "🌙",
        _ => "💻"
    };

    private void OnThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
    }
}

