        <label>Theme</label>
        <select @bind="SelectedTheme">
            <option value="@Services.Theme.Light">Light</option>
            <option value="@Services.Theme.Dark">Dark</option>
            <option value="@Services.Theme.System">System</option>
        </select>
    </div>

    <div class="setting-group">
        <label>Accent Color</label>
        <input type="color" @bind="AccentColor" />
        <span style="color: @AccentColor;">@AccentColor</span>
    </div>
</div>

<p><em>Changes apply immediately to all components (check the header indicator).</em></p>

